import{_ as a,o as s,c as o,ae as i}from"./chunks/framework.Co1PSFSm.js";const k=JSON.parse('{"title":"","description":"在 Deno Deploy 上部署 Fresh","frontmatter":{"description":"在 Deno Deploy 上部署 Fresh"},"headers":[],"relativePath":"zh/deployment/deno-deploy.md","filePath":"zh/deployment/deno-deploy.md"}'),n={name:"zh/deployment/deno-deploy.md"};function t(l,e,r,p,h,d){return s(),o("div",null,[...e[0]||(e[0]=[i(`<p>部署 Fresh 的推荐方式是使用 <a href="https://deno.com/deploy" target="_blank" rel="noreferrer">Deno Deploy</a>。它会自动为拉取请求创建分支预览、收集请求和 HTTP 指标，以及开箱即用地收集<a href="/zh/advanced/opentelemetry.html">跟踪数据</a>。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><ol><li>登录 <a href="https://deno.com/deploy" target="_blank" rel="noreferrer">Deno Deploy</a></li><li>创建新应用</li><li>链接你的 GitHub 仓库</li><li>选择 &quot;Fresh&quot; 预设（如果它没有自动被检测到）</li></ol><p>每次你合并到 <code>main</code> 分支时，都会创建一个新的生产部署。</p><h2 id="构建步骤" tabindex="-1">构建步骤 <a class="header-anchor" href="#构建步骤" aria-label="Permalink to &quot;构建步骤&quot;">​</a></h2><p>当选择 Fresh 预设时，Deno Deploy 会在部署期间自动运行 <code>deno task build</code>。请确保你的 <code>deno.json</code> 中有正确的构建任务：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deno serve -A _fresh/server.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>你可以在 Deno Deploy 仪表板的<strong>设置 &gt; 环境变量</strong>部分设置环境变量。这些可以通过 <code>Deno.env.get()</code> 在运行时访问。</p><p>对于需要在<a href="/zh/concepts/islands.html">岛屿</a>代码（客户端）中使用的变量，请使用 <code>FRESH_PUBLIC_</code> 前缀——请参阅<a href="/zh/advanced/environment-variables.html">环境变量</a>。</p><h2 id="自定义域名" tabindex="-1">自定义域名 <a class="header-anchor" href="#自定义域名" aria-label="Permalink to &quot;自定义域名&quot;">​</a></h2><p>自定义域名可以在 Deno Deploy 仪表板的<strong>设置 &gt; 域名</strong>部分进行配置。Deno Deploy 会自动为你的域名配置 TLS 证书。</p><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><p>如果你的部署无法启动：</p><ol><li>确保已运行 <code>deno task build</code>（检查是否选择了 Fresh 预设）</li><li>验证你的入口文件是 <code>_fresh/server.js</code>，而不是 <code>main.ts</code>——Fresh 2 会在构建步骤期间生成服务器入口</li><li>在 Deno Deploy 仪表板中查看部署日志以获取具体错误信息</li></ol><p>有关更多详细信息，请参阅 <a href="https://docs.deno.com/deploy/manual/" target="_blank" rel="noreferrer">Deno Deploy 文档</a>。</p>`,16)])])}const u=a(n,[["render",t]]);export{k as __pageData,u as default};
